clc;
clear;
close all;
%%
%[text] ## =========================================================
%[text] MARA-SYS : Maritime Communication System COMPARISON: 1. Existing System (Without RL) 2. Proposed MARA-RL System (With Reinforcement Learning)
%[text] Outputs: Throughput Sum Rate Energy Consumption Spectral Efficiency Power Consumption
%[text] Maritime Rician Fading + 6G Satellite Model
%[text] ## =========================================================
%[text] ## =========================
%[text] SYSTEM PARAMETERS
%[text] ## =========================
Iterations      = 200;
K_subchannels   = 48;
N_vessels       = 20;

Bandwidth       = 15e3;              % 15 KHz
NoisePower      = 1e-13;

TTI             = 0.05;              % 50 ms

Pmax_dBm        = 43;
Pmax            = 10^((Pmax_dBm-30)/10);

SeaState        = 4;
%%
%[text] ## Rician K-factor
K_dB = 2.1 - 0.3*SeaState;
K = 10^(K_dB/10);
%%
%[text] ## RL PARAMETERS
alpha = 0.1;              % learning rate
gamma = 0.95;             % discount factor
epsilon = 0.2;

Q_table = zeros(N_vessels,2);
%%
%[text] ## =========================
%[text] STORAGE VARIABLES
%[text] ## =========================
%[text] ## WITHOUT RL
Throughput_NoRL = zeros(1,Iterations);
SumRate_NoRL = zeros(1,Iterations);
Energy_NoRL = zeros(1,Iterations);
SE_NoRL = zeros(1,Iterations);
Power_NoRL = zeros(1,Iterations);
%%
%[text] ## WITH RL
Throughput_RL = zeros(1,Iterations);
SumRate_RL = zeros(1,Iterations);
Energy_RL = zeros(1,Iterations);
SE_RL = zeros(1,Iterations);
Power_RL = zeros(1,Iterations);
%%
%[text] ## =========================================================
%[text] EXISTING SYSTEM (WITHOUT RL)
%[text] ## =========================================================
for t = 1:Iterations
    
    total_rate = 0;
    total_energy = 0;
    total_power = 0;
    total_SE = 0;
    
    for i = 1:N_vessels
        
%%
%[text] ## RICIAN CHANNEL
        LOS = sqrt(K/(K+1));
        
        NLOS = sqrt(1/(2*(K+1))) * ...
            (randn(1,K_subchannels) + 1i*randn(1,K_subchannels));
        
        h = LOS + NLOS;
        
        channel_gain = abs(h).^2;
        
%%
%[text] ## FIXED POWER ALLOCATION
        P_tx = (Pmax/K_subchannels) * ones(1,K_subchannels);
        
%%
%[text] ## SINR
        SINR = (P_tx .* channel_gain) ./ NoisePower;
        
%%
%[text] ## RATE
        Rate = Bandwidth * log2(1 + SINR);
        
%%
%[text] ## TOTAL RATE
        total_rate = total_rate + sum(Rate);
        
%%
%[text] ## ENERGY
        energy = sum(P_tx) * TTI;
        total_energy = total_energy + energy;
        
%%
%[text] ## POWER
        total_power = total_power + sum(P_tx);
        
%%
%[text] ## SPECTRAL EFFICIENCY
        total_SE = total_SE + mean(log2(1 + SINR));
        
    end
    
    Throughput_NoRL(t) = total_rate / 1e6;
    SumRate_NoRL(t) = total_rate / 1e6;
    Energy_NoRL(t) = total_energy;
    Power_NoRL(t) = total_power;
    SE_NoRL(t) = total_SE / N_vessels;
    
end
%%
%[text] ## =========================================================
%[text] PROPOSED MARA SYSTEM (WITH RL)
%[text] ## =========================================================
for t = 1:Iterations
    
    total_rate = 0;
    total_energy = 0;
    total_power = 0;
    total_SE = 0;
    
    for i = 1:N_vessels
        
%%
%[text] ## RICIAN CHANNEL
        LOS = sqrt(K/(K+1));
        
        NLOS = sqrt(1/(2*(K+1))) * ...
            (randn(1,K_subchannels) + 1i*randn(1,K_subchannels));
        
        h = LOS + NLOS;
        
        channel_gain = abs(h).^2;
        
%%
%[text] ## RL ACTION SELECTION
        if rand < epsilon
            action = randi([1 2]);
        else
            [~,action] = max(Q_table(i,:));
        end
        
%%
%[text] ## ACTION:
%[text] 1 -\> LOW POWER 2 -\> HIGH POWER
        if action == 1
            P_tx = 0.5 * (Pmax/K_subchannels) * ones(1,K_subchannels);
        else
            P_tx = 1.2 * (Pmax/K_subchannels) * ones(1,K_subchannels);
        end
        
%%
%[text] ## SINR
        SINR = (P_tx .* channel_gain) ./ NoisePower;
        
%%
%[text] ## SHANNON RATE
        Rate = Bandwidth * log2(1 + SINR);
        
        vessel_rate = sum(Rate);
        
%%
%[text] ## ENERGY
        energy = sum(P_tx) * TTI;
        
%%
%[text] ## REWARD FUNCTION
        reward = 0.5*(vessel_rate/1e6) ...
               - 0.2*energy;
        
%%
%[text] ## Q-LEARNING UPDATE
        oldQ = Q_table(i,action);
        
        nextMax = max(Q_table(i,:));
        
        newQ = oldQ + alpha * ...
              (reward + gamma*nextMax - oldQ);
        
        Q_table(i,action) = newQ;
        
%%
%[text] ## UPDATE TOTALS
        total_rate = total_rate + vessel_rate;
        total_energy = total_energy + energy;
        total_power = total_power + sum(P_tx);
        total_SE = total_SE + mean(log2(1 + SINR));
        
    end
    
    Throughput_RL(t) = total_rate / 1e6;
    SumRate_RL(t) = total_rate / 1e6;
    Energy_RL(t) = total_energy;
    Power_RL(t) = total_power;
    SE_RL(t) = total_SE / N_vessels;
    
%%
%[text] ## EPSILON DECAY
    epsilon = max(0.01, epsilon*0.995);
    
end
%%
%[text] ## =========================================================
%[text] SMOOTHING
%[text] ## =========================================================
window = 10;

Throughput_NoRL = movmean(Throughput_NoRL,window);
Throughput_RL = movmean(Throughput_RL,window);

SumRate_NoRL = movmean(SumRate_NoRL,window);
SumRate_RL = movmean(SumRate_RL,window);
%%
%[text] ## =========================================================
%[text] PLOTS
%[text] ## =========================================================
%[text] ## 1. THROUGHPUT
figure; %[output:6766a6fa]
plot(Throughput_NoRL,'r','LineWidth',2); %[output:6766a6fa]
hold on; %[output:6766a6fa]
plot(Throughput_RL,'b','LineWidth',2); %[output:6766a6fa]

xlabel('Iterations'); %[output:6766a6fa]
ylabel('Throughput (Mbps)'); %[output:6766a6fa]
title('Throughput Comparison'); %[output:6766a6fa]
legend('Without RL','With RL'); %[output:6766a6fa]
box on; %[output:6766a6fa]
grid on; %[output:6766a6fa]
%%
%[text] ## 2. SUM RATE
figure; %[output:0da517c0]
plot(SumRate_NoRL,'k','LineWidth',2); %[output:0da517c0]
hold on; %[output:0da517c0]
plot(SumRate_RL,'g','LineWidth',2); %[output:0da517c0]

xlabel('TTI'); %[output:0da517c0]
ylabel('Sum Rate (Mbps)'); %[output:0da517c0]
title('Sum Rate Convergence'); %[output:0da517c0]
legend('Without RL','With RL'); %[output:0da517c0]
grid on; %[output:0da517c0]
%%
%[text] ## 3. ENERGY
figure; %[output:712b9b47]
plot(Energy_NoRL,'m','LineWidth',2); %[output:712b9b47]
hold on; %[output:712b9b47]
plot(Energy_RL,'c','LineWidth',2); %[output:712b9b47]

xlabel('Iterations'); %[output:712b9b47]
ylabel('Energy Consumption (J)'); %[output:712b9b47]
title('Energy Consumption Comparison'); %[output:712b9b47]
legend('Without RL','With RL'); %[output:712b9b47]
grid on; %[output:712b9b47]
%%
%[text] ## 4. SPECTRAL EFFICIENCY
figure; %[output:337289bb]
plot(SE_NoRL,'r','LineWidth',2); %[output:337289bb]
hold on; %[output:337289bb]
plot(SE_RL,'b','LineWidth',2); %[output:337289bb]

xlabel('Iterations'); %[output:337289bb]
ylabel('Spectral Efficiency (bits/s/Hz)'); %[output:337289bb]
title('Rician Channel Spectrum Efficiency'); %[output:337289bb]
legend('Without RL','With RL'); %[output:337289bb]
grid on; %[output:337289bb]
%%
%[text] ## 5. POWER CONSUMPTION
figure; %[output:0fc46a78]
plot(Power_NoRL,'k','LineWidth',2); %[output:0fc46a78]
hold on; %[output:0fc46a78]
plot(Power_RL,'g','LineWidth',2); %[output:0fc46a78]

xlabel('Iterations'); %[output:0fc46a78]
ylabel('Power Consumption (W)'); %[output:0fc46a78]
title('Power Consumption Comparison'); %[output:0fc46a78]
legend('Without RL','With RL'); %[output:0fc46a78]
grid on; %[output:0fc46a78]
%%
%[text] ## =========================================================
%[text] RESULTS DISPLAY
%[text] ## =========================================================
fprintf('\n==================================================\n'); %[output:81777d9e]
fprintf(' EXISTING SYSTEM (WITHOUT RL)\n'); %[output:2b95a784]
fprintf('==================================================\n'); %[output:9790678b]

fprintf('Average Throughput        : %.2f Mbps\n', ... %[output:group:333df02f] %[output:95ec01fd]
    mean(Throughput_NoRL)); %[output:group:333df02f] %[output:95ec01fd]

fprintf('Average Sum Rate          : %.2f Mbps\n', ... %[output:group:7b3bd0e8] %[output:8ea7e1ad]
    mean(SumRate_NoRL)); %[output:group:7b3bd0e8] %[output:8ea7e1ad]

fprintf('Average Energy            : %.4f J\n', ... %[output:group:6c55ebea] %[output:3c541ef9]
    mean(Energy_NoRL)); %[output:group:6c55ebea] %[output:3c541ef9]

fprintf('Average Spectral Efficiency : %.2f bits/s/Hz\n', ... %[output:group:0df581fc] %[output:169c35ca]
    mean(SE_NoRL)); %[output:group:0df581fc] %[output:169c35ca]

fprintf('Average Power Consumption : %.2f W\n', ... %[output:group:901515b6] %[output:047b09db]
    mean(Power_NoRL)); %[output:group:901515b6] %[output:047b09db]

fprintf('\n==================================================\n'); %[output:016b8fed]
fprintf(' PROPOSED MARA-RL SYSTEM\n'); %[output:9c746f15]
fprintf('==================================================\n'); %[output:2dd73472]

fprintf('Average Throughput        : %.2f Mbps\n', ... %[output:group:334b3606] %[output:666e2a5e]
    mean(Throughput_RL)); %[output:group:334b3606] %[output:666e2a5e]

fprintf('Average Sum Rate          : %.2f Mbps\n', ... %[output:group:69f021d0] %[output:24f0070b]
    mean(SumRate_RL)); %[output:group:69f021d0] %[output:24f0070b]

fprintf('Average Energy            : %.4f J\n', ... %[output:group:53ab3042] %[output:24c51bfc]
    mean(Energy_RL)); %[output:group:53ab3042] %[output:24c51bfc]

fprintf('Average Spectral Efficiency : %.2f bits/s/Hz\n', ... %[output:group:6ddf0f89] %[output:43fe9a68]
    mean(SE_RL)); %[output:group:6ddf0f89] %[output:43fe9a68]

fprintf('Average Power Consumption : %.2f W\n', ... %[output:group:1275f533] %[output:8c94389c]
    mean(Power_RL)); %[output:group:1275f533] %[output:8c94389c]

fprintf('\n==================================================\n'); %[output:04c94e49]
%%
%[text] ## =========================================================
%[text] IMPROVEMENT ANALYSIS
%[text] ## =========================================================
Throughput_Improve = ...
    ((mean(Throughput_RL)-mean(Throughput_NoRL)) ...
    /mean(Throughput_NoRL))*100;

Energy_Reduction = ...
    ((mean(Energy_NoRL)-mean(Energy_RL)) ...
    /mean(Energy_NoRL))*100;

fprintf('\nTHROUGHPUT IMPROVEMENT = %.2f %%n', ... %[output:group:5fbf138f] %[output:26f21a8e]
    Throughput_Improve); %[output:group:5fbf138f] %[output:26f21a8e]

fprintf('ENERGY REDUCTION = %.2f %%n', ... %[output:group:821a2606] %[output:1de989af]
    Energy_Reduction); %[output:group:821a2606] %[output:1de989af]

fprintf('\nSimulation Completed Successfully.\n'); %[output:3bf59bd0]

